System.Collections.IEnumerator Run(){
 var r=UnityEngine.Object.FindObjectOfType<Character.Control.PaddleCharacterVisual>();
 foreach(var a in r.GetComponentsInChildren<Character.Control.ArmsSimulation>())a.enabled=false;
 foreach(var t in UnityEngine.Object.FindObjectsOfType<Character.Control.TargetMovement>())t.enabled=false;
 foreach(var rb in r.GetComponentsInChildren<UnityEngine.Rigidbody2D>())rb.simulated=false;
 foreach(var c in UnityEngine.Object.FindObjectsOfType<Cinemachine.CinemachineVirtualCamera>())c.enabled=false;
 r.Pose();r.torso.enabled=r.paddle.enabled=r.leftUpper.enabled=r.rightUpper.enabled=true;
 foreach(var sr in r.GetComponentsInChildren<UnityEngine.SpriteRenderer>())if(sr.name.StartsWith("Grip palm ")||sr.name.StartsWith("Forearm segment "))sr.enabled=true;
 var cam=UnityEngine.Camera.main;cam.orthographicSize=2.5f;cam.transform.position=r.body.position+new UnityEngine.Vector3(0,.3f,-10);
 float error=0;
 for(int i=0;i<48;i++){
  var q=UnityEngine.Quaternion.Euler(0,0,90f+i*7.5f);r.tool.rotation=q;r.tool.position=r.body.position+q*new UnityEngine.Vector3((.75f+1.1f*(.5f+.5f*UnityEngine.Mathf.Sin(i*.23f))),.074f,0);r.Pose();error=UnityEngine.Mathf.Max(error,r.HandError);
  yield return null;
  if(i%12==0){UnityEngine.ScreenCapture.CaptureScreenshot(System.IO.Path.GetFullPath("scripts/player-raised-grips-20261111/visual-"+i+".png"));yield return new UnityEngine.WaitForEndOfFrame();}
 }
 string log="PASS 48 continuous visual poses in actual Play, no physical input test; wrist error="+error;
 System.IO.File.WriteAllText("scripts/player-raised-grips-20261111/visual.txt",log);UnityEngine.Debug.Log(log);
}
return Run();
